// Stitch's exported colors, spacing, typography, and command-deck structure are
// implemented in styles.css. All numerical results below come from Python APIs.
const pages=[
  ['overview','Overview','space_dashboard','OPERATIONS & CONTROL'],
  ['control-tower','Control Tower','hub'],
  ['operations-overview','Operations Overview','directions_boat'],
  ['market-intelligence','Market Intelligence','analytics','ANALYTICS & FORECASTING'],
  ['forecasts','Forecasts','trending_up'],
  ['decision-twin','Decision Twin','schema'],
  ['charter-workbench','Charter Workbench','balance','CHARTER EXECUTION & STRESS TESTING'],
  ['decision-arena','Decision Arena','compare_arrows'],
  ['scenario-lab','Scenario Lab','science'],
  ['simulation-backtest','Simulation Backtest','history'],
  ['data-integrations','Data & Integrations','cable','PLATFORM & DATA REPOSITORIES'],
  ['data-explorer','Data Explorer','database']
];
const integrationTabs=['Connections','Data Quality','Overrides','Audit Trail','Model & Data Limitations','Decision Parameters','Model Cards','Model Status'];
const explorerTabs=['Route Freight Series','Dataset','Correlation Matrix','Quality Audit','Validate & Preview Dataset'];
const presets={
 'East Coast Disruption':{freight_rate_shock_pct:12,port_congestion_shock_pct:55,vessel_availability_shock_pct:-30,weather_risk_level:'High'},
 'Freight Rate Spike':{freight_rate_shock_pct:25},
 'Paradip Congestion':{port_congestion_shock_pct:80,target_port:'Paradip'},
 'Vessel Shortage':{vessel_availability_shock_pct:-50},
 'Demurrage Escalation':{demurrage_rate_shock_pct:30},
 'Severe Weather Risk':{weather_risk_level:'Severe'},
 'Market Relief':{freight_rate_shock_pct:-15,port_congestion_shock_pct:-30,vessel_availability_shock_pct:25}
};
const state={page:location.hash.slice(2)||'control-tower',tab:0,route:'AU_GLT -> IN_PDP',model:'Auto',horizon:14,
 cargo:'Coking Coal',quantity:75000,earliest:'',latest:'',shock:{},preset:'',theme:localStorage.getItem('freightiq-theme')||'dark',
 cache:new Map(),result:{},tablePage:0,compareRoutes:[],notice:'',busy:false,
 arenaCount:250,arenaSeed:42,uncertaintyScale:1,arenaSample:0};
const $=q=>document.querySelector(q), esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<span class="icon ${cls}">${esc(name)}</span>`;
const n=(v,d=0)=>Number.isFinite(Number(v))?Number(v).toLocaleString('en-IN',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
const cr=usd=>Number.isFinite(Number(usd))?'₹'+n(Number(usd)*84/1e7,2)+' Cr':'—';
const lakh=usd=>Number.isFinite(Number(usd))?'₹'+n(Number(usd)*84/1e5,1)+' lakh':'—';
const ir=usd=>Number.isFinite(Number(usd))?'₹'+n(Number(usd)*84,0):'—';
const date=s=>s?new Date(s).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'—';
const chip=(s,c='cyan')=>`<span class="chip ${c}">${esc(s)}</span>`;
const btn=(text,action,kind='',extra='')=>`<button class="btn ${kind}" data-action="${action}" ${extra}>${text}</button>`;
const section=(title,body,subtitle='',aside='')=>`<section class="section"><div class="section-head"><div><h2>${title}</h2>${subtitle?`<p class="caption">${subtitle}</p>`:''}</div>${aside}</div>${body}</section>`;
const kpi=(title,val,sub='',tag='')=>`<div class="kpi"><div class="label"><span>${esc(title)}</span>${tag?`<span class="cyan">${esc(tag)}</span>`:''}</div><div class="value num">${val}</div><div class="caption">${sub}</div></div>`;
const activityRow=(title,ico,detail,value)=>`<div class="activity-row"><div><strong>${icon(ico,'teal')} ${esc(title)}</strong><div class="caption">${esc(detail)}</div></div><strong class="num cyan">${esc(value)}</strong></div>`;
const head=(eyebrow,title,desc,right='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${right}</div>`;
const field=(label,id,type,value,options)=>`<label class="field"><span>${esc(label)}</span>${options?`<select id="${id}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select>`:`<input id="${id}" type="${type}" value="${esc(value??'')}" ${type==='number'?'min="0"':''}>`}</label>`;
const selectOpts=(items,labelKey='display_label',key='route_key')=>items.map(x=>[x[key],x[labelKey]||x[key]]);
const formatCell=v=>v===null||v===undefined?'—':typeof v==='number'?n(v,Math.abs(v)%1?2:0):typeof v==='string'&&/^\d{4}-\d\d-\d\dT\d/.test(v)?esc(date(v)):esc(v);
const rationale=s=>`<div class="rationale">${(Array.isArray(s)?s:[s||'Lowest modeled feasible total cost.']).filter(Boolean).map(t=>`<p>${icon('chevron_right','teal')}${esc(String(t).trim())}</p>`).join('')}</div>`;
function table(rows,cols,limit=100){if(!rows?.length)return `<div class="notice">No records available for this state.</div>`;
 const keys=cols||Object.keys(rows[0]);return `<div class="table-outer"><button class="table-expand" title="Inspect table full screen" data-table-fullscreen>${icon('open_in_full')} Full screen</button><div class="table-wrap"><table><thead><tr>${keys.map(c=>`<th title="Sort visible rows by ${esc(c)}" data-sort>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,limit).map(r=>`<tr>${keys.map(c=>`<td>${formatCell(r[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`}
function shell(){let nav='';for(const [id,title,ico,group] of pages){if(group)nav+=`<div class="nav-group">${group}</div>`;nav+=`<a class="nav ${id===state.page?'active':''}" href="#/${id}" data-page="${id}">${icon(ico)}<span>${title}</span>${id===state.page?'<span class="dot"></span>':''}</a>`}
 const routeName=state.catalog?.routes.find(r=>r.route_key===state.route)?.display_label||'Hay Point → Paradip';
 return `<aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">${icon('radar')}</div><div><div class="brand-main">Freight<span>IQ</span> ${chip('v4.2','green')}</div><div class="brand-sub">Maritime Intelligence</div></div></div><div class="nav-scroll">${nav}</div><div class="side-bottom"><div class="status-box"><span class="label">DATA STATUS</span>${chip('DEMO / SYNTHETIC','amber')}<span class="tiny">Forecast Engine</span><span class="tiny cyan">Auto Select</span></div><div class="theme-row"><span>${icon('terminal')} SYS_ONLINE</span><button data-action="theme">${icon(state.theme==='dark'?'light_mode':'dark_mode')}</button></div></div></aside>
 <div class="topbar"><div class="top-left"><button class="btn small mobile-menu" data-action="menu">${icon('menu')}</button><span class="tiny">${icon('explore','cyan')} FIQ-CORE <span class="slash">/</span> <strong>COMMAND DECK</strong></span></div><div class="shipment-chip"><span class="teal">${icon('sailing')}</span><strong class="mono">FIQ-2026-0001</strong><span class="slash">•</span><span class="cargo">${n(state.quantity)} t ${esc(state.cargo)}</span><span class="slash">•</span><span class="route teal">${esc(routeName)}</span>${chip('DEMO-CALIBRATED','green')}</div><div class="top-right"><span class="coverage muted">DATA COVERAGE<br><strong id="coverage">Jan 2024 – Aug 2026</strong></span><a class="btn small connectors" href="#/data-integrations">${icon('database','teal')} Source status</a></div></div>
 <div class="content"><main id="main" class="page"><div class="loading">LOADING PYTHON ENGINE DATA…</div></main></div>`}
function setShell(){document.documentElement.className=state.theme;$('#app').innerHTML=shell();}
function toast(message,type='success'){state.notice=message;let old=$('#toast');if(old)old.remove();let el=document.createElement('div');el.id='toast';el.className=`notice ${type}`;el.style='position:fixed;right:20px;bottom:20px;z-index:100;max-width:410px;box-shadow:var(--shadow)';el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),5000)}
async function api(path,body){const key=path+JSON.stringify(body||'');if(!body&&state.cache.has(key))return state.cache.get(key);const init=body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{};let res=await fetch('/api/'+path,init);if(!res.ok){let d;try{d=await res.json()}catch{d={detail:res.statusText}};throw Error(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail))}let data=await res.json();if(!body)state.cache.set(key,data);return data}
const request=()=>({route_key:state.route,cargo_type:state.cargo,quantity_tonnes:state.quantity,vessel_class:state.vesselClass||'Auto',horizon:state.horizon,model_name:state.model,earliest_date:state.earliest||null,latest_date:state.latest||null,shock:{...state.shock}});
function applyShipment(route,cargo=state.cargo,quantity=state.quantity){if(route!==state.route){state.vesselClass='Auto'}if(route!==state.route||cargo!==state.cargo||quantity!==state.quantity)state.result={};state.route=route;state.cargo=cargo;state.quantity=quantity}
async function loadPair(...paths){return Promise.all(paths.map(p=>Array.isArray(p)?api(p[0],p[1]):api(p)))}
let voyageMapModule;
function setMain(html){voyageMapModule?.disposeVoyageMap();document.querySelectorAll('.plotly-chart').forEach(el=>window.Plotly?.purge(el));$('#main').innerHTML=html+`<div class="site-foot">FreightIQ decision-support prototype · Synthetic freight and market data · Model outputs require commercial verification.</div>`;mountCharts($('#main'));let mapEl=$('#voyage-map-card');if(mapEl)import('./voyage-map.js').then(module=>{voyageMapModule=module;if(mapEl.isConnected)module.mountVoyageMap(mapEl)}).catch(e=>{console.error(e);if(mapEl.isConnected)mapEl.querySelector('.voyage-map-surface').textContent='Geographic map unavailable. Port and voyage metrics remain below.'})}
function fail(error){setMain(`<div class="error-box"><strong>Unable to load this view.</strong><br>${esc(error.message||error)}<div class="form-actions">${btn('Retry','retry','primary')}</div></div>`)}
function routeMap(context){return `<div class="voyage-intel" id="voyage-map-card" data-context="${esc(JSON.stringify(context))}"><div class="voyage-top"><div class="voyage-endpoints"><strong>${esc(context.origin)} <span>→</span> ${esc(context.destination)}</strong><small>SELECTED MARITIME CORRIDOR</small></div>${chip('DEMO / SYNTHETIC','amber')}</div><div class="voyage-controls" role="tablist" aria-label="Voyage route view"><button type="button" class="voyage-tab active" data-voyage-view="selected" role="tab" aria-selected="true">SELECTED ROUTE</button><button type="button" class="voyage-tab" data-voyage-view="alternatives" role="tab" aria-selected="false">ALTERNATIVES</button><button type="button" class="voyage-reset" title="Fit selected voyage to map" aria-label="Reset map view">${icon('center_focus_strong')} RESET VIEW</button></div><div class="voyage-map-wrap"><div class="voyage-map-surface" role="application" aria-label="Interactive map of ${esc(context.origin)} to ${esc(context.destination)}">LOADING GEOGRAPHIC MAP…</div><div class="voyage-map-note">ILLUSTRATIVE CORRIDOR · ROUTING NOT VERIFIED</div></div><div class="voyage-alternatives" hidden><strong>Navigation alternatives unavailable</strong><p>No verified alternative maritime route geometry or cost comparison is connected. Charter date alternatives in the optimizer are separate decisions.</p></div><div class="voyage-metrics"><div title="Approximate distance along an open-source sea graph; not a verified passage plan"><span>VOYAGE DISTANCE</span><strong data-voyage-distance>—</strong><small>Approx. graph distance</small></div><div title="Sea-graph distance divided by configured vessel speed in knots; excludes delays"><span>EST. TRANSIT</span><strong data-voyage-transit>—</strong><small>At configured speed</small></div><div title="The app does not produce a validated combined route-level exposure rating"><span>ROUTE EXPOSURE</span><strong>NOT EVALUATED</strong><small>No route-level score</small></div></div><div class="voyage-signals" data-voyage-signals></div><div class="voyage-footer">SYNTHETIC SCENARIO · NOT LIVE AIS TRACKING <span>· Port authority / master reference points · Natural Earth land · Sea graph corridor</span></div></div>`}
function voyageContext(rec,latest={}){let route=state.catalog.routes.find(x=>x.route_key===state.route),scenarioResult=state.result.scenario,costRow=scenarioResult?.comparison_table?.find(r=>r.metric==='Total Logistics Cost');return {routeKey:state.route,origin:route?.origin_name||'Origin',destination:route?.destination_name||'Destination',cargo:state.cargo,quantity:state.quantity,vessel:rec.recommended_vessel,speed:state.catalog.vessel_speeds_knots?.[rec.recommended_vessel],congestion:latest.port_congestion_score,waitingHours:latest.avg_waiting_hours,weather:latest.weather_risk_score,scenario:scenarioResult?.route_key===state.route&&Object.keys(state.shock).length?{...state.shock,costBaseline:costRow?.baseline,costStressed:costRow?.stress_scenario}:null}}
function plotChart(traces,layout={},opts={}){return `<div class="chart plotly-chart ${opts.tall?'tall':opts.large?'large':''}" data-plotly="${esc(JSON.stringify({traces,layout,opts}))}" role="img" aria-label="${esc(opts.label||'Interactive data chart')}"></div>`}
function mountCharts(scope=document){
 if(!window.Plotly){scope.querySelectorAll('.plotly-chart').forEach(el=>el.textContent='Interactive chart library unavailable.');return}
 scope.querySelectorAll('.plotly-chart:not([data-mounted])').forEach(el=>{
  el.dataset.mounted='true';
  try{
   let spec=JSON.parse(el.dataset.plotly),light=state.theme==='light',fg=light?'#466478':'#a8b9c9',grid=light?'#c4d7e0':'#244155';
   let base={paper_bgcolor:'rgba(0,0,0,0)',plot_bgcolor:light?'#f9fcfd':'#020f1f',font:{family:'JetBrains Mono, monospace',size:10,color:fg},margin:{l:62,r:22,t:18,b:42},hovermode:'x unified',showlegend:false,dragmode:'zoom',xaxis:{type:'date',showgrid:false,linecolor:grid,showspikes:true,spikemode:'across',spikecolor:'#41deb9'},yaxis:{gridcolor:grid,griddash:'dot',zerolinecolor:grid,showspikes:true,spikecolor:'#41deb9'}};
   let layout={...base,...spec.layout,xaxis:{...base.xaxis,...spec.layout?.xaxis},yaxis:{...base.yaxis,...spec.layout?.yaxis}};
   window.Plotly.newPlot(el,spec.traces,layout,{responsive:true,scrollZoom:true,displaylogo:false,displayModeBar:true,doubleClick:'reset',modeBarButtonsToRemove:['lasso2d','select2d'],toImageButtonOptions:{format:'png',filename:'freightiq-chart'}}).catch(e=>{console.error(e);el.textContent='Chart could not be drawn.'});
  }catch(e){console.error(e);el.textContent='Chart could not be drawn.'}
 });
}
function lineChart(hist,forecast=[],opts={}){const h=(hist||[]).filter(x=>Number.isFinite(Number(x.value)));const f=(forecast||[]).filter(x=>Number.isFinite(Number(x.value)));if(!h.length)return '<div class="notice">Chart data unavailable.</div>';const scale=opts.inr?84:1,unit=opts.unit||(opts.inr?'₹/t':'value'),money=opts.inr?'₹':'',fmt=`${money}%{y:,.2f} ${unit.replace('₹','').trim()}`;let traces=[{type:'scatter',mode:'lines',name:opts.historyLabel||'Synthetic history',x:h.map(p=>p.date),y:h.map(p=>Number(p.value)*scale),line:{color:f.length?'#92a5b4':'#35d6e8',width:2},hovertemplate:`%{x|%d %b %Y}<br>${fmt}<extra>${opts.historyLabel||'Synthetic history'}</extra>`}];if(!f.length&&h.some(p=>Number.isFinite(p.ma)))traces.push({type:'scatter',mode:'lines',name:'Moving average',x:h.filter(p=>Number.isFinite(p.ma)).map(p=>p.date),y:h.filter(p=>Number.isFinite(p.ma)).map(p=>Number(p.ma)*scale),line:{color:'#41deb9',width:1.5,dash:'dot'},hovertemplate:`%{x|%d %b %Y}<br>${fmt}<extra>Moving average</extra>`});if(f.length){let band=f.filter(p=>Number.isFinite(Number(p.lower))&&Number.isFinite(Number(p.upper)));if(band.length){traces.push({type:'scatter',mode:'lines',name:'Lower bound',x:band.map(p=>p.date),y:band.map(p=>Number(p.lower)*scale),line:{width:0},hoverinfo:'skip',showlegend:false});traces.push({type:'scatter',mode:'lines',name:opts.bandLabel||'Forecast interval',x:band.map(p=>p.date),y:band.map(p=>Number(p.upper)*scale),line:{color:'#b59aff',width:2,dash:'dash'},fill:'tonexty',fillcolor:'rgba(53,214,232,0.13)',hovertemplate:`%{x|%d %b %Y}<br>Upper ${fmt}<extra>Upper bound</extra>`});traces.push({type:'scatter',mode:'lines',name:'Lower bound',x:band.map(p=>p.date),y:band.map(p=>Number(p.lower)*scale),line:{color:'#b59aff',width:2,dash:'dash'},hovertemplate:`%{x|%d %b %Y}<br>Lower ${fmt}<extra>Lower bound</extra>`})}traces.push({type:'scatter',mode:'lines+markers',name:opts.forecastLabel||'Forecast',x:[h.at(-1).date,...f.map(p=>p.date)],y:[Number(h.at(-1).value)*scale,...f.map(p=>Number(p.value)*scale)],line:{color:'#35d6e8',width:3},marker:{size:3},hovertemplate:`%{x|%d %b %Y}<br>${fmt}<extra>${opts.forecastLabel||'Forecast'}</extra>`})}let layout={yaxis:{title:{text:unit,font:{size:10}},tickformat:',.0f'},xaxis:{rangeslider:{visible:h.length>180,thickness:.1}},shapes:f.length?[{type:'line',xref:'x',yref:'paper',x0:h.at(-1).date,x1:h.at(-1).date,y0:0,y1:1,line:{color:'#41deb9',width:1,dash:'dash'}}]:[]};return plotChart(traces,layout,opts)}
function tabs(labels){return `<div class="tabs" role="tablist">${labels.map((t,i)=>`<button class="tab ${state.tab===i?'active':''}" role="tab" aria-selected="${state.tab===i}" data-tab="${i}">${esc(t)}</button>`).join('')}</div>`}
function routeSelect(routes,id='route'){return field('Active route',id,'',state.route,selectOpts(routes))}
const countryNames={AU:'Australia',ID:'Indonesia',ZA:'South Africa',BR:'Brazil',MZ:'Mozambique',IN:'India'};
function originControls(prefix){const routes=state.catalog.routes,selected=routes.find(r=>r.route_key===state.route)||routes[0],country=selected.origin_port_id.split('_')[0],countries=[...new Set(routes.map(r=>r.origin_port_id.split('_')[0]))].map(x=>[x,countryNames[x]||x]),origins=[...new Map(routes.filter(r=>r.origin_port_id.startsWith(country+'_')).map(r=>[r.origin_port_id,[r.origin_port_id,r.origin_name]])).values()],dests=[...new Map(routes.filter(r=>r.origin_port_id===selected.origin_port_id).map(r=>[r.destination_port_id,[r.destination_port_id,r.destination_name]])).values()];return `${field('Origin country',`${prefix}-country`,'',country,countries)}${field('Origin port',`${prefix}-origin`,'',selected.origin_port_id,origins)}${field('Destination port',`${prefix}-dest`,'',selected.destination_port_id,dests)}`}
function resolveSelection(prefix){let country=$(`#${prefix}-country`)?.value,origin=$(`#${prefix}-origin`)?.value,dest=$(`#${prefix}-dest`)?.value,route=state.catalog.routes.find(r=>r.origin_port_id===origin&&r.destination_port_id===dest);if(!route)throw Error(`No calibrated route for ${countryNames[country]||country} / ${origin||'origin'} → ${dest||'destination'}. Select a supported route.`);return route.route_key}

function chartRows(records){return (records||[]).map(r=>({date:r.date,value:Number(r.freight_rate),ma:Number(r.freight_ma_14)}))}
function monthlyChartRows(records){let months=new Map();for(const r of records||[]){let key=String(r.date).slice(0,7),a=months.get(key)||{sum:0,count:0};a.sum+=Number(r.freight_rate);a.count++;months.set(key,a)}let out=[...months].map(([month,a])=>({date:month+'-01',value:a.sum/a.count}));return out.map((x,i)=>({...x,ma:out.slice(Math.max(0,i-2),i+1).reduce((s,r)=>s+r.value,0)/Math.min(3,i+1)}))}
function forecastRows(fc){return (fc?.forecast_df||[]).map(r=>({date:r.date,value:Number(r.predicted_freight_rate),lower:Number(r.lower_ci),upper:Number(r.upper_ci)}))}
function legend(forecast=true){return `<div class="legend"><span><i class="swatch hist"></i>Synthetic history</span>${forecast?'<span><i class="swatch"></i>Forecast</span><span><i class="swatch bound"></i>Upper / lower bounds</span><span><i class="swatch band"></i>model interval</span>':'<span><i class="swatch"></i>14-day moving average</span>'}</div>`}
function summaryActions(){return `<div class="actions">${btn(`${icon('arrow_forward')} View Recommendation`,'go-charter','primary')}${btn(`${icon('compare_arrows')} Compare Strategies`,'go-arena')}${btn(`${icon('science')} Run Scenario Stress Test`,'go-scenario')}${btn(`${icon('picture_as_pdf')} Download PDF Report`,'report')}</div>`}
async function overview(control){let [data,fc,opt,twin]=await loadPair(`web/data?route_key=${encodeURIComponent(state.route)}`,['web/forecast',{...request(),horizon:30}],['web/optimize',{...request(),horizon:30}],['web/decision-twin',request()]);let rows=data.records,latest=rows.at(-1),rec=opt.recommendation,hero=twin.hero_summary,spot=Number(latest.freight_rate),routeName=state.catalog.routes.find(x=>x.route_key===state.route)?.display_label||state.route;let title=control?'Control Tower':'Overview';
 const kpis=`<div class="grid g4">${kpi('Expected cost',cr(rec.expected_total_logistics_cost_usd),'Modeled logistics cost','[TCO_CALC]')}${kpi('Charter window',esc(rec.recommended_charter_date),`${esc(rec.recommended_vessel)} vessel class`,'[OPT_LAYCAN]')}${kpi('Robustness score',`${n(hero.robustness_score)}<small> / 100</small>`,'Composite score across 1,000 simulated futures; not probability','[MC_SIM]')}${kpi('Spot benchmark',`${ir(spot)}<small> / t</small>`,'Latest synthetic route observation','[DEMO]')}</div>`;
 const intro=`<section class="section accent"><div class="section-head"><div><div class="eyebrow">ACTIVE SHIPMENT · RECOMMENDED ACTION</div><h2>FIQ-2026-0001 · ${n(state.quantity)} t ${esc(state.cargo)}</h2><p class="caption">${esc(routeName)} · Route-specific synthetic history</p></div>${chip('DEMO-CALIBRATED','green')}</div>${kpis}<div class="notice" style="margin:12px 0">${esc(Array.isArray(rec.why)?rec.why.join(' '):rec.why||'The Python optimizer selected the lowest modeled feasible candidate.')}</div>${summaryActions()}</section>`;
 const route=section('VOYAGE INTELLIGENCE',routeMap(voyageContext(rec,latest)),'Geospatial route intelligence · Selected maritime corridor');
 const history=section('Synthetic Spot Freight Rate Trajectory',lineChart(monthlyChartRows(rows),[],{inr:true,label:'Synthetic route freight rates'}) ,'Monthly mean of daily synthetic series · ₹/tonne',legend(false));
 const activity=section('Shipment Activity',`<div class="activity-list">${activityRow('Destination Port Queue','anchor',`Average wait ${n(latest.avg_waiting_hours,1)} h · synthetic`,`${n(latest.port_congestion_score,1)} / 100`)}${activityRow('Vessel Availability','sailing','Route supply · synthetic',`${n(latest.vessel_availability_count)} vessels`)}${activityRow('Bunker Context','local_gas_station','Synthetic reference level',n(latest.bunker_context,1))}${activityRow('Weather Risk','thunderstorm','Synthetic route risk score',n(latest.weather_risk_score,1))}</div>`,'Context signals · not a live feed');
 const fchart=section('30-Day Predictive Freight Rate Outlook',lineChart(chartRows(rows).slice(-55),forecastRows(fc),{inr:true,large:true,label:'Freight forecast with model interval'}),'Synthetic observations, selected model forecast and model interval · ₹/tonne',`${chip(fc.selected_model,'cyan')} ${legend(true)}`);
 setMain(`${head('RADAR 01 :: DISPATCH CONSOLE',title,'Freight exposure and modeled chartering decisions for industrial dry-bulk procurement.',chip('SYNTHETIC DAILY TAPE','amber'))}<div class="page-stack"><div class="grid g8-4">${intro}${route}</div><div class="grid g8-4">${history}${activity}</div>${fchart}</div>`);
}
