 const matrix=table(candidates.map((c,i)=>({Rank:i+1,Vessel:c.vessel_class,Date:c.charter_date,Route:c.route,'Freight (₹/t)':ir(c.unit_freight_usd_per_tonne),'Expected Cost':cr(c.total_logistics_cost_usd),Status:i===0?'Recommended':'Feasible'})),['Rank','Vessel','Date','Route','Freight (₹/t)','Expected Cost','Status'],30);
