 const scenarioTable=table(Object.entries(opt.scenarios||{}).map(([name,c])=>({Scenario:name,Date:c.charter_date,Vessel:c.vessel_class,Freight:cr(c.freight_cost_usd),Demurrage:lakh(c.demurrage_cost_usd),Total:cr(c.total_logistics_cost_usd)})));
 const routeSpec=state.catalog.routes.find(x=>x.route_key===state.route)?.route_spec;
