 let shipment=`<div class="form-grid">${field('Cargo Type','twin-cargo','',state.cargo,[['Coking Coal','Coking Coal'],['Iron Ore','Iron Ore']])}${field('Quantity (t)','twin-quantity','number',state.quantity)}${originControls('twin')}</div><div class="form-actions">${btn(`${icon('sync')} Re-Simulate Candidate Matrix`,'rerun-twin','primary')}${chip('1,000 SIMULATED FUTURES','amber')}</div>`;
 setMain(`${head('STOCHASTIC DECISION ENGINE','Decision Twin','Stress-test charter choices across modeled futures, with explicit regret and decision stability.',`${btn(`${icon('picture_as_pdf')} Download Decision Twin Report`,'twin-report')}`)}${state.preset?`<div class="notice warn" style="margin-bottom:16px">Active scenario: ${esc(state.preset)} · See Scenario Lab for the baseline/stressed comparison.</div>`:''}<div class="grid twin-layout">${section('Shipment Input',shipment,'Inputs for the Python Decision Twin engine')}<div class="page-stack"><div class="grid g4">${kpi('Recommended action',`${esc(h.recommended_vessel)} · ${esc(h.recommended_date)}`,'Simulated preferred vessel and date')}${kpi('Expected logistics cost',`₹${n(h.expected_cost_inr_cr,2)} Cr`,'Mean across simulated futures')}${kpi('Decision robustness',`${n(h.robustness_score)} / 100`,'Composite score · not probability')}${kpi('Expected regret',`₹${n(h.expected_regret_inr_lakh,1)} lakh`,'Modeled downside versus hindsight')}</div>${section('Decision Surface',heat,'Expected modeled cost (₹ Cr) across vessel/port and date choices · hover for detail')}${section('Simulated Freight Futures',lineChart(fanRows.slice(0,1),fanRows.slice(1),{inr:true,large:true,label:'Simulated freight futures',historyLabel:'Simulation start',forecastLabel:'Simulated median'}),'Median and 10–90% envelope · modeled futures, not freight forecast confidence band')}${section('What Would Change This Decision?',`<div class="grid g4">${(twin.counterfactuals||[]).map(c=>`<div class="kpi"><div class="label">${esc(c.trigger_event)}</div><p style="margin:8px 0">${esc(c.condition)}</p><p class="caption">${esc(c.action)}</p></div>`).join('')}</div>`,'Model-derived heuristic tipping points')}</div></div>`);
