document.addEventListener('click',e=>{let expand=e.target.closest('[data-table-fullscreen]');if(expand){let outer=expand.closest('.table-outer');if(document.fullscreenElement)document.exitFullscreen();else outer?.requestFullscreen?.();return}
 let sort=e.target.closest('[data-sort]');if(sort){let tableEl=sort.closest('table'),headers=[...tableEl.tHead.rows[0].cells],index=headers.indexOf(sort),body=tableEl.tBodies[0],ascending=sort.dataset.order!=='asc';headers.forEach(h=>{h.dataset.order='';h.removeAttribute('aria-sort')});sort.dataset.order=ascending?'asc':'desc';sort.setAttribute('aria-sort',ascending?'ascending':'descending');let value=row=>row.cells[index]?.textContent.trim()||'';let numeric=s=>Number(s.replace(/[₹$,%\s]/g,'').replace(/,/g,''));[...body.rows].sort((a,b)=>{let av=value(a),bv=value(b),an=numeric(av),bn=numeric(bv),cmp=av&&bv&&Number.isFinite(an)&&Number.isFinite(bn)?an-bn:av.localeCompare(bv,undefined,{numeric:true});return ascending?cmp:-cmp}).forEach(row=>body.append(row));return}
 let t=e.target.closest('[data-tab],[data-preset],[data-action],[data-page]');if(!t)return;if(t.dataset.tab!==undefined){state.tab=Number(t.dataset.tab);state.tablePage=0;render()}else if(t.dataset.preset){state.preset=t.dataset.preset;state.shock={...presets[state.preset]};state.result.scenario=null;render()}else if(t.dataset.action){e.preventDefault();runAction(t.dataset.action)}else if(t.dataset.page){$('#sidebar')?.classList.remove('open')}});
document.addEventListener('change',e=>{let id=e.target.id;if(id==='shock-weather'||id==='shock-port'){state.preset='';return}let prefix=id?.startsWith('charter-')?'charter':id?.startsWith('twin-')?'twin':null;if(!prefix||!['country','origin'].some(s=>id===`${prefix}-${s}`))return;let country=$(`#${prefix}-country`).value,origin=$(`#${prefix}-origin`),dest=$(`#${prefix}-dest`);if(id.endsWith('country')){let routes=state.catalog.routes.filter(r=>r.origin_port_id.startsWith(country+'_'));let unique=[...new Map(routes.map(r=>[r.origin_port_id,r])).values()];origin.innerHTML=unique.map(r=>`<option value="${esc(r.origin_port_id)}">${esc(r.origin_name)}</option>`).join('')}let avail=state.catalog.routes.filter(r=>r.origin_port_id===origin.value);dest.innerHTML=[...new Map(avail.map(r=>[r.destination_port_id,r])).values()].map(r=>`<option value="${esc(r.destination_port_id)}">${esc(r.destination_name)}</option>`).join('')});
